('tasks', 'bg6anh', '{"createdAt": 1792160009000, "due": "2026-11-04", "grade": 6, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["compass – com-pa", "calculator – máy tính cầm tay", "uniform – đồng phục", "pencil sharpener – gọt bút chì"], "cap": "School things", "fig": "schoolthings", "h": "School things", "k": "Tiếng Anh 6 · Unit 1", "say": "Chào các em, hôm nay học Unit một, My new school. Đầu tiên là đồ dùng học tập. [en] Compass. Là cái com pa. [en] Calculator. Là máy tính cầm tay. [en] Uniform. Là đồng phục. [en] Pencil sharpener. Là cái gọt bút chì.", "type": "slide"}, {"b": ["play football / music", "do homework / exercise", "have lessons / breakfast", "study science / English"], "h": "Verbs at school", "say": "Các động từ thường gặp ở trường. [en] Play football. Play music. [en] Do homework. Do exercise. [en] Have lessons. Have breakfast. [en] Study science. Study English.", "type": "slide"}, {"a": 0, "e": "Ta nói \"do homework\".", "o": ["do", "play", "have", "study"], "p": 4, "q": "Choose the correct verb: \"___ homework\"", "type": "q"}, {"b": ["I / You / We / They + V", "He / She / It + V-s / V-es", "Dùng cho thói quen và sự thật hiển nhiên."], "f": "She goes to school by bike.", "h": "Present simple", "say": "Thì hiện tại đơn dùng để nói về thói quen và sự thật hiển nhiên. Với chủ ngữ he, she, it, động từ thêm s hoặc es. [en] She goes to school by bike.", "type": "slide"}, {"a": 0, "e": "Chủ ngữ số ít \"My brother\" nên \"study\" thành \"studies\".", "o": ["studies", "study", "studying", "is study"], "p": 4, "q": "My brother ___ English on Monday.", "type": "q"}, {"b": ["always > usually > often > sometimes > rarely > never", "Đứng trước động từ thường, sau động từ \"be\"."], "cap": "Adverbs of frequency", "ex": "I usually walk to school. He is never late.", "fig": "freq", "h": "Adverbs of frequency", "say": "Trạng từ chỉ tần suất đứng trước động từ thường và sau động từ to be. [en] I usually walk to school. [en] He is never late.", "type": "slide"}, {"a": 1, "e": "Trạng từ tần suất đứng sau \"be\".", "o": ["She always is late.", "She is always late.", "Always she is late.", "She is late always."], "p": 4, "q": "Choose the correct sentence:", "type": "q"}], "subject": "anh", "title": "Unit 1 · My New School"}'::jsonb),
('tasks', 'bg6khtn', '{"createdAt": 1792160006000, "due": "2026-10-31", "grade": 6, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Tế bào là đơn vị cấu trúc và chức năng của cơ thể sống.", "Hầu hết tế bào rất nhỏ, phải dùng kính hiển vi mới quan sát được.", "Có sinh vật chỉ gồm một tế bào, có sinh vật gồm rất nhiều tế bào."], "h": "Tế bào là gì?", "k": "KHTN 6 · Tế bào", "say": "Chào các em. Mọi cơ thể sống đều được cấu tạo từ tế bào. Tế bào là đơn vị cấu trúc và chức năng của cơ thể sống. Hầu hết tế bào rất nhỏ, phải dùng kính hiển vi mới thấy được. Có sinh vật chỉ gồm một tế bào, có sinh vật gồm rất nhiều tế bào.", "type": "slide"}, {"b": ["Màng tế bào: bao bọc, kiểm soát các chất đi vào và đi ra.", "Tế bào chất: nơi diễn ra phần lớn các hoạt động sống.", "Nhân hoặc vùng nhân: chứa vật chất di truyền, điều khiển hoạt động của tế bào."], "cap": "Ba thành phần chính của tế bào", "fig": "cell", "h": "Ba thành phần chính", "type": "slide"}, {"a": 2, "e": "Nhân chứa vật chất di truyền, là trung tâm điều khiển.", "o": ["Màng tế bào", "Tế bào chất", "Nhân tế bào", "Thành tế bào"], "p": 4, "q": "Thành phần nào điều khiển mọi hoạt động sống của tế bào?", "type": "q"}, {"b": ["Tế bào nhân sơ (ví dụ vi khuẩn): chưa có màng nhân, vật chất di truyền nằm ở vùng nhân.", "Tế bào nhân thực (thực vật, động vật, nấm): có màng nhân bao bọc."], "cap": "Tế bào nhân sơ và tế bào nhân thực", "fig": "prokeuk", "h": "Tế bào nhân sơ và nhân thực", "type": "slide"}, {"a": 0, "e": "Vi khuẩn chưa có màng nhân nên là tế bào nhân sơ.", "o": ["Tế bào nhân sơ", "Tế bào nhân thực"], "p": 4, "q": "Vi khuẩn được cấu tạo từ loại tế bào nào?", "type": "q"}, {"b": ["Tế bào thực vật có thành tế bào và lục lạp.", "Tế bào động vật không có thành tế bào và lục lạp.", "Lục lạp chứa diệp lục, giúp cây quang hợp."], "cap": "So sánh tế bào thực vật và động vật", "fig": "plantanimal", "h": "Tế bào thực vật và động vật", "say": "Tế bào thực vật có thành tế bào và lục lạp, còn tế bào động vật thì không có. Lục lạp chứa diệp lục giúp cây quang hợp. Sau bài này, các em vào phòng thí nghiệm kính hiển vi để quan sát tế bào vảy hành nhé.", "type": "slide"}, {"a": 2, "e": "Lục lạp giúp cây quang hợp, tế bào động vật không có.", "o": ["Nhân", "Màng tế bào", "Lục lạp", "Tế bào chất"], "p": 4, "q": "Bào quan nào chỉ có ở tế bào thực vật?", "type": "q"}], "subject": "khtn", "title": "Tế bào – đơn vị cơ sở của sự sống"}'::jsonb),
('tasks', 'bg6sudia', '{"createdAt": 1792160007000, "due": "2026-11-02", "grade": 6, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Trái Đất có dạng hình cầu.", "Bán kính Trái Đất khoảng 6 370 km.", "Chiều dài đường Xích đạo khoảng 40 076 km."], "cap": "Trái Đất hình cầu", "fig": "globe_size", "h": "Hình dạng và kích thước Trái Đất", "k": "Địa lí 6", "say": "Chào các em. Trái Đất của chúng ta có dạng hình cầu, bán kính khoảng sáu nghìn ba trăm bảy mươi ki lô mét, và đường Xích đạo dài khoảng bốn mươi nghìn không trăm bảy mươi sáu ki lô mét.", "type": "slide"}, {"b": ["Kinh tuyến là đường nối cực Bắc với cực Nam trên bề mặt quả Địa Cầu.", "Kinh tuyến gốc (0°) đi qua đài thiên văn Greenwich ở Luân Đôn (Anh).", "Các kinh tuyến đều dài bằng nhau."], "cap": "Kinh tuyến và kinh tuyến gốc", "fig": "globe_mer", "h": "Kinh tuyến", "say": "Kinh tuyến là đường nối cực Bắc với cực Nam trên quả Địa Cầu. Kinh tuyến gốc, ứng với không độ, đi qua đài thiên văn Greenwich ở Luân Đôn, nước Anh. Các kinh tuyến đều dài bằng nhau.", "type": "slide"}, {"a": 0, "e": "Kinh tuyến gốc 0° đi qua đài thiên văn Greenwich, Luân Đôn.", "o": ["Đài thiên văn Greenwich", "Thủ đô Pa-ri", "Đường Xích đạo", "Cực Bắc"], "p": 4, "q": "Kinh tuyến gốc đi qua địa điểm nào?", "type": "q"}, {"b": ["Vĩ tuyến là những vòng tròn vuông góc với kinh tuyến.", "Vĩ tuyến gốc (0°) là đường Xích đạo, dài nhất.", "Càng về hai cực, vĩ tuyến càng ngắn."], "cap": "Vĩ tuyến và đường Xích đạo", "fig": "globe_par", "h": "Vĩ tuyến", "type": "slide"}, {"a": 0, "e": "Xích đạo là vĩ tuyến gốc và dài nhất.", "o": ["Xích đạo", "Chí tuyến Bắc", "Vòng cực Bắc", "Kinh tuyến gốc"], "p": 4, "q": "Vĩ tuyến dài nhất là:", "type": "q"}, {"b": ["Vị trí một điểm được xác định bằng kinh độ và vĩ độ.", "Kinh độ: số độ từ kinh tuyến gốc đến kinh tuyến đi qua điểm đó.", "Vĩ độ: số độ từ Xích đạo đến vĩ tuyến đi qua điểm đó."], "cap": "Tọa độ địa lí của điểm A", "fig": "globe_coord", "h": "Tọa độ địa lí", "type": "slide"}, {"a": 0, "e": "Tọa độ địa lí = kinh độ + vĩ độ.", "o": ["Kinh độ và vĩ độ", "Độ cao và độ sâu", "Chiều dài và chiều rộng"], "p": 4, "q": "Tọa độ địa lí của một điểm gồm:", "type": "q"}], "subject": "sudia", "title": "Trái Đất: kinh tuyến, vĩ tuyến và tọa độ địa lí"}'::jsonb),
('tasks', 'bg6toan', '{"createdAt": 1792160005000, "due": "2026-10-30", "grade": 6, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Nếu a chia hết cho b thì a là bội của b, còn b là ước của a.", "Ví dụ: 12 chia hết cho 3 nên 3 là ước của 12, 12 là bội của 3."], "h": "Ước và bội", "k": "Toán 6", "say": "Chào các em. Hôm nay ta học số nguyên tố và hợp số. Nhắc lại: nếu a chia hết cho b thì a là bội của b, còn b là ước của a. Ví dụ, mười hai chia hết cho ba nên ba là ước của mười hai.", "type": "slide"}, {"b": ["Số nguyên tố: số tự nhiên lớn hơn 1, chỉ có hai ước là 1 và chính nó.", "Hợp số: số tự nhiên lớn hơn 1, có nhiều hơn hai ước.", "Số 0 và số 1 không là số nguyên tố, cũng không là hợp số."], "cap": "Các số nguyên tố từ 1 đến 30", "ex": "Các số nguyên tố nhỏ hơn 20: 2, 3, 5, 7, 11, 13, 17, 19.", "fig": "sieve", "h": "Số nguyên tố và hợp số", "say": "Số nguyên tố là số tự nhiên lớn hơn một, chỉ có hai ước là một và chính nó. Hợp số là số tự nhiên lớn hơn một, có nhiều hơn hai ước. Lưu ý số không và số một không là số nguyên tố, cũng không là hợp số. Các số nguyên tố nhỏ hơn hai mươi là hai, ba, năm, bảy, mười một, mười ba, mười bảy và mười chín.", "type": "slide"}, {"a": 2, "e": "21 = 3 · 7 nên 21 có các ước 1, 3, 7, 21.", "o": ["13", "17", "21", "19"], "p": 4, "q": "Số nào là hợp số?", "type": "q"}, {"b": ["2 là số nguyên tố nhỏ nhất.", "2 là số nguyên tố chẵn duy nhất.", "Mọi số chẵn lớn hơn 2 đều là hợp số."], "h": "Số 2 đặc biệt", "say": "Số hai rất đặc biệt. Đây là số nguyên tố nhỏ nhất, và cũng là số nguyên tố chẵn duy nhất. Mọi số chẵn lớn hơn hai đều chia hết cho hai nên đều là hợp số.", "type": "slide"}, {"a": 2, "e": "Số 2 là số nguyên tố và là số chẵn.", "o": ["Mọi số nguyên tố đều là số lẻ", "Số 1 là số nguyên tố", "2 là số nguyên tố chẵn duy nhất", "Hợp số có đúng hai ước"], "p": 4, "q": "Khẳng định nào đúng?", "type": "q"}, {"b": ["Viết một số dưới dạng tích các thừa số nguyên tố.", "Chia dần cho các số nguyên tố từ nhỏ đến lớn."], "cap": "Cây phân tích 60 ra thừa số nguyên tố", "f": "60 = 2² · 3 · 5", "fig": "factortree", "h": "Phân tích ra thừa số nguyên tố", "say": "Phân tích một số ra thừa số nguyên tố là viết số đó dưới dạng tích các thừa số nguyên tố. Ta chia dần cho các số nguyên tố từ nhỏ đến lớn. Ví dụ, sáu mươi bằng hai mũ hai nhân ba nhân năm.", "type": "slide"}, {"a": 0, "e": "36 = 2 · 2 · 3 · 3 = 2² · 3². Các cách còn lại có thừa số không phải số nguyên tố.", "o": ["2² · 3²", "4 · 9", "2 · 18", "6²"], "p": 4, "q": "Phân tích 36 ra thừa số nguyên tố được:", "type": "q"}], "subject": "toan", "title": "Số nguyên tố. Hợp số"}'::jsonb),
('tasks', 'bg6van', '{"createdAt": 1792160008000, "due": "2026-11-03", "grade": 6, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Truyện dân gian kể về sự kiện, nhân vật liên quan đến lịch sử.", "Thường có yếu tố kì ảo.", "Thể hiện thái độ, cách đánh giá của nhân dân với nhân vật và sự kiện."], "h": "Truyền thuyết là gì?", "k": "Ngữ văn 6 · Truyền thuyết", "say": "Chào các em. Hôm nay chúng ta học truyền thuyết Thánh Gióng. Truyền thuyết là truyện dân gian kể về các sự kiện, nhân vật có liên quan đến lịch sử, thường có yếu tố kì ảo, thể hiện cách nhân dân đánh giá các nhân vật và sự kiện đó.", "type": "slide"}, {"b": ["Bà mẹ ướm chân vào vết chân to ngoài đồng, về nhà thụ thai.", "Lên ba tuổi, Gióng vẫn không biết nói, biết cười, chẳng biết đi.", "Nghe sứ giả tìm người đánh giặc Ân, Gióng bỗng cất tiếng nói."], "cap": "Bà mẹ ướm chân vào vết chân to", "fig": "footprint", "h": "Sự ra đời kì lạ", "type": "slide"}, {"a": 0, "e": "Gióng nói lần đầu để xin đi đánh giặc: lòng yêu nước.", "o": ["Ý thức đánh giặc cứu nước", "Mong muốn được ăn no", "Nỗi sợ giặc Ân", "Muốn đi chơi xa"], "p": 4, "q": "Tiếng nói đầu tiên của Gióng thể hiện điều gì?", "type": "q"}, {"b": ["Gióng lớn nhanh như thổi, bà con góp gạo nuôi Gióng.", "Gióng vươn vai thành tráng sĩ, mặc áo giáp sắt, cưỡi ngựa sắt ra trận.", "Roi sắt gãy, Gióng nhổ những cụm tre bên đường quật vào giặc."], "cap": "Cụm tre đánh giặc", "fig": "bamboo", "h": "Gióng ra trận", "type": "slide"}, {"a": 0, "e": "Gióng được cả làng nuôi lớn: người anh hùng của nhân dân.", "o": ["Sức mạnh của Gióng là sức mạnh của cả cộng đồng", "Gióng ăn rất nhiều", "Làng có nhiều gạo", "Gióng được vua ban thưởng"], "p": 4, "q": "Chi tiết \"bà con góp gạo nuôi Gióng\" có ý nghĩa gì?", "type": "q"}, {"b": ["Gióng là hình tượng người anh hùng đánh giặc giữ nước.", "Thể hiện sức mạnh đoàn kết toàn dân.", "Hội Gióng ở đền Phù Đổng và đền Sóc được UNESCO ghi danh là di sản văn hóa phi vật thể năm 2010."], "h": "Ý nghĩa truyện", "say": "Thánh Gióng là hình tượng người anh hùng đánh giặc giữ nước, thể hiện sức mạnh đoàn kết của toàn dân. Ngày nay, Hội Gióng ở đền Phù Đổng và đền Sóc đã được UNESCO ghi danh là di sản văn hóa phi vật thể đại diện của nhân loại năm hai nghìn không trăm mười.", "type": "slide"}, {"a": 1, "e": "Gióng bay về trời ở núi Sóc Sơn, trở thành bất tử.", "o": ["Về làng làm ruộng", "Cởi áo giáp sắt, cả người và ngựa bay về trời", "Lên làm vua", "Đi đánh giặc ở nước khác"], "p": 4, "q": "Đánh tan giặc, Gióng đã làm gì?", "type": "q"}], "subject": "van", "title": "Truyền thuyết Thánh Gióng"}'::jsonb),
('tasks', 'bg9anh', '{"createdAt": 1792160004000, "due": "2026-11-04", "grade": 9, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["artisan – thợ thủ công", "handicraft – đồ thủ công", "community helper – người giúp đỡ cộng đồng", "facility – cơ sở vật chất (thư viện, công viên…)"], "cap": "Some handicrafts: conical hat and paper lantern", "fig": "lantern", "h": "Vocabulary", "k": "Tiếng Anh 9 · Unit 1", "say": "Chào các em, hôm nay chúng ta học Unit một, Local community. Đầu tiên là từ vựng. [en] Artisan. Nghĩa là thợ thủ công. [en] Handicraft. Nghĩa là đồ thủ công. [en] Community helper. Là người giúp đỡ cộng đồng. [en] Facility. Là cơ sở vật chất như thư viện hay công viên.", "type": "slide"}, {"b": ["Dùng sau các động từ know, decide, wonder, ask, show…", "what / where / when / how / who + to V"], "ex": "She showed me how to make a paper lantern.", "f": "I don''t know what to do.", "h": "Question word + to-infinitive", "say": "Điểm ngữ pháp hôm nay là từ để hỏi đi với động từ nguyên mẫu có to. Cấu trúc này thường đứng sau các động từ như know, decide, wonder, ask, show. [en] I don''t know what to do. [en] She showed me how to make a paper lantern.", "type": "slide"}, {"a": 0, "e": "\"how to + V\": cách để làm gì.", "o": ["how to", "what to", "to how", "how"], "p": 4, "q": "Can you tell me ___ get to the post office?", "type": "q"}, {"b": ["We haven''t decided where to go this weekend.", "He asked when to start the project.", "I wonder who to invite to the party."], "h": "More examples", "say": "Thêm vài ví dụ nhé. [en] We haven''t decided where to go this weekend. [en] He asked when to start the project. [en] I wonder who to invite to the party.", "type": "slide"}, {"a": 0, "e": "\"what to buy\": mua gì.", "o": ["what", "where", "who", "why"], "p": 4, "q": "I don''t know ___ to buy for my mum''s birthday.", "type": "q"}, {"b": ["firefighter – puts out fires", "police officer – keeps people safe", "delivery person – brings things to your house", "garbage collector – collects rubbish"], "cap": "Community helpers", "fig": "helpers", "h": "Community helpers", "say": "Cuối cùng là những người giúp đỡ cộng đồng. [en] A firefighter puts out fires. [en] A police officer keeps people safe. [en] A delivery person brings things to your house. [en] A garbage collector collects rubbish.", "type": "slide"}, {"a": 0, "e": "Firefighter: lính cứu hỏa.", "o": ["A firefighter", "A delivery person", "An artisan", "A police officer"], "p": 4, "q": "Who puts out fires?", "type": "q"}], "subject": "anh", "title": "Unit 1 · Local Community"}'::jsonb),
('tasks', 'bg9khtn', '{"createdAt": 1792160001000, "due": "2026-10-31", "grade": 9, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Điện trở R cho biết mức độ cản trở dòng điện của dây dẫn.", "Đơn vị điện trở là ohm, kí hiệu Ω; 1 kΩ = 1 000 Ω.", "Cùng một hiệu điện thế, điện trở càng lớn thì dòng điện càng nhỏ."], "cap": "Điện trở cản trở dòng electron", "fig": "resistor", "h": "Điện trở là gì?", "k": "KHTN 9 · Điện", "say": "Chào các em. Bài hôm nay nói về điện trở và định luật Ohm. Điện trở, kí hiệu R, cho biết dây dẫn cản trở dòng điện nhiều hay ít. Đơn vị của điện trở là ohm. Một ki lô ohm bằng một nghìn ohm. Với cùng một hiệu điện thế, điện trở càng lớn thì dòng điện chạy qua càng nhỏ.", "type": "slide"}, {"b": ["Cường độ dòng điện qua dây dẫn tỉ lệ thuận với hiệu điện thế đặt vào hai đầu dây.", "Và tỉ lệ nghịch với điện trở của dây.", "I đo bằng ampe (A), U đo bằng vôn (V), R đo bằng ohm (Ω)."], "cap": "Tam giác ghi nhớ: che ô cần tìm để thấy công thức", "ex": "U = 6 V, R = 12 Ω thì I = 6 : 12 = 0,5 A.", "f": "I = U / R", "fig": "ohmtri", "h": "Định luật Ohm", "say": "Định luật Ohm phát biểu: cường độ dòng điện chạy qua dây dẫn tỉ lệ thuận với hiệu điện thế đặt vào hai đầu dây, và tỉ lệ nghịch với điện trở của dây. Công thức là I bằng U chia R. Ví dụ, hiệu điện thế sáu vôn, điện trở mười hai ohm thì cường độ dòng điện là không phẩy năm ampe.", "type": "slide"}, {"a": 0, "e": "I = U : R = 12 : 24 = 0,5 A.", "o": ["0,5 A", "2 A", "288 A", "36 A"], "p": 4, "q": "Đặt hiệu điện thế 12 V vào hai đầu điện trở 24 Ω. Cường độ dòng điện là:", "type": "q"}, {"b": ["Ampe kế mắc nối tiếp với điện trở để đo cường độ dòng điện.", "Vôn kế mắc song song với điện trở để đo hiệu điện thế.", "Đồ thị I theo U là một đường thẳng đi qua gốc tọa độ."], "cap": "Sơ đồ mắc ampe kế và vôn kế", "fig": "circuit", "h": "Đo U và I trong phòng thí nghiệm", "say": "Trong phòng thí nghiệm, ampe kế được mắc nối tiếp với điện trở để đo cường độ dòng điện, còn vôn kế được mắc song song với điện trở để đo hiệu điện thế. Khi vẽ đồ thị cường độ dòng điện theo hiệu điện thế, ta được một đường thẳng đi qua gốc tọa độ.", "type": "slide"}, {"a": 0, "e": "Ampe kế mắc nối tiếp để toàn bộ dòng điện chạy qua nó.", "o": ["Nối tiếp", "Song song", "Mắc thế nào cũng được"], "p": 4, "q": "Ampe kế phải được mắc như thế nào với điện trở cần đo dòng điện?", "type": "q"}, {"b": ["Chiều dài dây: dây càng dài, điện trở càng lớn.", "Tiết diện dây: dây càng to, điện trở càng nhỏ.", "Vật liệu làm dây, thể hiện qua điện trở suất ρ."], "cap": "Chiều dài và tiết diện ảnh hưởng đến điện trở", "f": "R = ρ · ℓ / S", "fig": "wires", "h": "Điện trở phụ thuộc vào gì?", "say": "Điện trở của một dây dẫn phụ thuộc vào ba yếu tố. Dây càng dài thì điện trở càng lớn. Dây càng to, tức tiết diện càng lớn, thì điện trở càng nhỏ. Và điện trở còn phụ thuộc vật liệu làm dây, thể hiện qua điện trở suất. Sau bài này, các em vào phòng thí nghiệm định luật Ohm để tự đo nhé.", "type": "slide"}, {"a": 2, "e": "I tỉ lệ thuận với U nên U gấp đôi thì I cũng gấp đôi.", "o": ["Giảm một nửa", "Không đổi", "Tăng gấp đôi", "Tăng gấp bốn"], "p": 4, "q": "Tăng hiệu điện thế giữa hai đầu một điện trở lên gấp đôi thì cường độ dòng điện:", "type": "q"}], "subject": "khtn", "title": "Điện trở và định luật Ohm"}'::jsonb),
('tasks', 'bg9sudia', '{"createdAt": 1792160002000, "due": "2026-11-02", "grade": 9, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Ngày 15/8/1945, Nhật Bản đầu hàng Đồng minh không điều kiện.", "Quân Nhật ở Đông Dương hoang mang, chính quyền thân Nhật tê liệt.", "Đảng Cộng sản Đông Dương nhận định thời cơ tổng khởi nghĩa đã đến."], "cap": "Ngày 15/8/1945: Nhật đầu hàng Đồng minh", "fig": "tl45_0", "h": "Thời cơ \"ngàn năm có một\"", "k": "Lịch sử 9", "say": "Chào các em. Hôm nay chúng ta tìm hiểu Cách mạng tháng Tám năm một nghìn chín trăm bốn mươi lăm. Ngày mười lăm tháng tám năm bốn lăm, Nhật Bản đầu hàng Đồng minh không điều kiện. Quân Nhật ở Đông Dương hoang mang, chính quyền thân Nhật tê liệt. Đảng nhận định thời cơ tổng khởi nghĩa đã đến.", "type": "slide"}, {"b": ["Đêm 13/8/1945, Ủy ban Khởi nghĩa toàn quốc ra Quân lệnh số 1, phát lệnh tổng khởi nghĩa.", "Ngày 14 và 15/8, Hội nghị toàn quốc của Đảng họp ở Tân Trào (Tuyên Quang).", "Ngày 16/8, Quốc dân Đại hội Tân Trào tán thành chủ trương tổng khởi nghĩa."], "cap": "Các mốc phát lệnh tổng khởi nghĩa", "fig": "tl45_1", "h": "Lệnh tổng khởi nghĩa", "say": "Đêm mười ba tháng tám, Ủy ban Khởi nghĩa toàn quốc ra Quân lệnh số một, phát lệnh tổng khởi nghĩa. Ngày mười bốn và mười lăm, Hội nghị toàn quốc của Đảng họp ở Tân Trào, Tuyên Quang. Ngày mười sáu tháng tám, Quốc dân Đại hội Tân Trào tán thành chủ trương tổng khởi nghĩa.", "type": "slide"}, {"a": 1, "e": "Ngày 15/8/1945 Nhật đầu hàng, kẻ thù trực tiếp suy yếu, đó là thời cơ.", "o": ["Nhật đảo chính Pháp", "Nhật Bản đầu hàng Đồng minh", "Pháp quay lại xâm lược", "Chiến tranh thế giới thứ hai bùng nổ"], "p": 4, "q": "Sự kiện nào tạo thời cơ cho Tổng khởi nghĩa tháng Tám năm 1945?", "type": "q"}, {"b": ["19/8/1945: khởi nghĩa giành chính quyền thắng lợi ở Hà Nội.", "23/8/1945: thắng lợi ở Huế.", "25/8/1945: thắng lợi ở Sài Gòn.", "Đến cuối tháng 8/1945, chính quyền trong cả nước về tay nhân dân."], "cap": "Giành chính quyền ở Hà Nội, Huế, Sài Gòn", "fig": "tl45_2", "h": "Giành chính quyền trên cả nước", "say": "Ngày mười chín tháng tám, khởi nghĩa giành chính quyền thắng lợi ở Hà Nội. Ngày hai mươi ba ở Huế. Ngày hai mươi lăm ở Sài Gòn. Đến cuối tháng tám năm bốn lăm, chính quyền trong cả nước đã về tay nhân dân.", "type": "slide"}, {"a": 0, "e": "Hà Nội 19/8, Huế 23/8, Sài Gòn 25/8.", "o": ["19/8/1945", "23/8/1945", "25/8/1945", "2/9/1945"], "p": 4, "q": "Khởi nghĩa giành chính quyền ở Hà Nội thắng lợi vào ngày nào?", "type": "q"}, {"b": ["Ngày 2/9/1945, tại Quảng trường Ba Đình (Hà Nội), Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập.", "Bản Tuyên ngôn khai sinh nước Việt Nam Dân chủ Cộng hòa.", "Ngày 2/9 trở thành ngày Quốc khánh của nước ta."], "cap": "Quốc kỳ nước Việt Nam", "fig": "flag", "h": "Nước Việt Nam Dân chủ Cộng hòa ra đời", "say": "Ngày hai tháng chín năm bốn lăm, tại Quảng trường Ba Đình, Hà Nội, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Từ đó, ngày hai tháng chín trở thành ngày Quốc khánh của nước ta.", "type": "slide"}, {"a": 0, "e": "Ngày 2/9/1945 tại Quảng trường Ba Đình, Hà Nội.", "o": ["Quảng trường Ba Đình", "Tân Trào", "Nhà hát Lớn Hà Nội", "Cố đô Huế"], "p": 4, "q": "Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập ở đâu?", "type": "q"}], "subject": "sudia", "title": "Cách mạng tháng Tám năm 1945"}'::jsonb),
('tasks', 'bg9toan', '{"createdAt": 1792160000000, "due": "2026-10-30", "grade": 9, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Có dạng ax + by = c, với a và b không đồng thời bằng 0.", "Mỗi cặp số (x₀; y₀) làm phương trình đúng là một nghiệm.", "Phương trình bậc nhất hai ẩn luôn có vô số nghiệm."], "cap": "Đồ thị phương trình 2x + y = 5", "f": "ax + by = c", "fig": "lineeq", "h": "Phương trình bậc nhất hai ẩn", "k": "Toán 9 · Chương 1", "say": "Chào các em, hôm nay chúng ta học hệ hai phương trình bậc nhất hai ẩn. Trước hết, phương trình bậc nhất hai ẩn có dạng a x cộng b y bằng c, trong đó a và b không đồng thời bằng không. Mỗi cặp số x không, y không làm phương trình đúng được gọi là một nghiệm. Phương trình này luôn có vô số nghiệm.", "type": "slide"}, {"a": 0, "e": "Thay x = 1, y = 3: 2·1 + 3 = 5, đúng.", "o": ["(1; 3)", "(2; 2)", "(0; 4)", "(3; 0)"], "p": 4, "q": "Cặp số nào là nghiệm của phương trình 2x + y = 5?", "type": "q"}, {"b": ["Gồm hai phương trình bậc nhất hai ẩn, viết chung trong dấu ngoặc nhọn.", "Nghiệm của hệ là cặp số thỏa mãn đồng thời cả hai phương trình.", "Giải hệ là tìm tất cả các nghiệm của hệ."], "cap": "Hai đường thẳng cắt nhau tại nghiệm của hệ", "f": "{ x + y = 5\n  x − y = 1", "fig": "twolines", "h": "Hệ hai phương trình", "say": "Hai phương trình bậc nhất hai ẩn viết chung trong dấu ngoặc nhọn tạo thành một hệ. Nghiệm của hệ là cặp số thỏa mãn đồng thời cả hai phương trình. Giải hệ nghĩa là tìm tất cả các nghiệm đó.", "type": "slide"}, {"b": ["Bước 1: Từ một phương trình, biểu diễn một ẩn theo ẩn kia.", "Bước 2: Thế vào phương trình còn lại, được phương trình một ẩn.", "Bước 3: Giải phương trình một ẩn rồi suy ra ẩn còn lại."], "cap": "Ba bước của phương pháp thế", "ex": "x + y = 5 và x − y = 1. Từ phương trình thứ hai: x = y + 1. Thế vào phương trình đầu: (y + 1) + y = 5, nên y = 2 và x = 3. Nghiệm là (3; 2).", "fig": "steps3", "h": "Phương pháp thế", "say": "Cách thứ nhất là phương pháp thế. Bước một, từ một phương trình, biểu diễn một ẩn theo ẩn kia. Bước hai, thế vào phương trình còn lại để được phương trình một ẩn. Bước ba, giải phương trình một ẩn rồi suy ra ẩn còn lại. Ví dụ, từ x trừ y bằng một ta có x bằng y cộng một. Thế vào phương trình x cộng y bằng năm, ta được y bằng hai, rồi x bằng ba.", "type": "slide"}, {"a": 1, "e": "Chuyển −2y sang vế phải thành +2y: x = 2y + 3.", "o": ["x = 3 − 2y", "x = 2y + 3", "x = 2y − 3", "x = (3 − y) : 2"], "p": 4, "q": "Từ phương trình x − 2y = 3, biểu diễn x theo y ta được:", "type": "q"}, {"b": ["Nhân mỗi phương trình với số thích hợp để hệ số của một ẩn bằng nhau hoặc đối nhau.", "Cộng hoặc trừ từng vế hai phương trình để khử bớt một ẩn.", "Giải phương trình một ẩn rồi tìm ẩn còn lại."], "cap": "Cộng từng vế để khử ẩn y", "ex": "2x + y = 7 và x − y = 2. Cộng từng vế: 3x = 9, nên x = 3 và y = 1.", "fig": "addelim", "h": "Phương pháp cộng đại số", "say": "Cách thứ hai là phương pháp cộng đại số. Ta làm cho hệ số của một ẩn ở hai phương trình bằng nhau hoặc đối nhau, rồi cộng hoặc trừ từng vế để khử ẩn đó. Ví dụ, hai x cộng y bằng bảy và x trừ y bằng hai. Cộng từng vế được ba x bằng chín, nên x bằng ba, y bằng một.", "type": "slide"}, {"a": 0, "e": "Cộng từng vế: 2x = 6 nên x = 3, suy ra y = 1.", "o": ["(3; 1)", "(1; 3)", "(2; 2)", "(4; 0)"], "p": 4, "q": "Nghiệm của hệ x + y = 4 và x − y = 2 là:", "type": "q"}], "subject": "toan", "title": "Hệ hai phương trình bậc nhất hai ẩn"}'::jsonb),
('tasks', 'bg9van', '{"createdAt": 1792160003000, "due": "2026-11-03", "grade": 9, "intro": "Vào lớp nghe giảng và trả lời câu hỏi giữa giờ để nhận điểm.", "kind": "lesson", "points": 12, "segs": [{"b": ["Nguyễn Dữ sống ở thế kỉ XVI.", "\"Chuyện người con gái Nam Xương\" là một trong 20 truyện của tập Truyền kì mạn lục, viết bằng chữ Hán.", "Truyện truyền kì kết hợp yếu tố hiện thực với yếu tố kì ảo."], "cap": "Tập Truyền kì mạn lục của Nguyễn Dữ", "fig": "book", "h": "Tác giả, tác phẩm", "k": "Ngữ văn 9 · Truyện truyền kì", "say": "Chào các em. Hôm nay chúng ta đọc hiểu Chuyện người con gái Nam Xương của Nguyễn Dữ, tác giả sống ở thế kỉ mười sáu. Đây là một trong hai mươi truyện của tập Truyền kì mạn lục, viết bằng chữ Hán. Truyện truyền kì kết hợp yếu tố hiện thực với yếu tố kì ảo.", "type": "slide"}, {"b": ["Người phụ nữ thùy mị, nết na, tư dung tốt đẹp.", "Thủy chung, hiếu thảo: một mình nuôi con, chăm sóc mẹ chồng khi chồng đi lính.", "Bị chồng là Trương Sinh nghi oan, nàng gieo mình xuống sông Hoàng Giang."], "h": "Nhân vật Vũ Nương", "say": "Vũ Nương là người phụ nữ thùy mị, nết na. Khi chồng là Trương Sinh đi lính, nàng một mình nuôi con, chăm sóc mẹ chồng chu đáo. Thế nhưng khi trở về, Trương Sinh nghi oan vợ, khiến nàng phải gieo mình xuống sông Hoàng Giang để giữ trọn danh tiết.", "type": "slide"}, {"a": 1, "e": "Bé Đản chỉ cái bóng của mẹ trên vách và gọi đó là cha.", "o": ["Vì nghe lời hàng xóm", "Vì lời bé Đản nói về \"người cha\" đêm nào cũng đến", "Vì đọc được một bức thư", "Vì mẹ già kể lại"], "p": 4, "q": "Vì sao Trương Sinh nghi oan cho vợ?", "type": "q"}, {"b": ["Vũ Nương chỉ bóng mình trên vách, nói với con đó là cha để dỗ con.", "Cái bóng vừa là nguyên nhân gây nỗi oan, vừa là chìa khóa giải oan.", "Chi tiết cho thấy tình thương con và nỗi nhớ chồng của Vũ Nương."], "cap": "Chi tiết cái bóng trên vách", "fig": "shadow", "h": "Chi tiết cái bóng", "say": "Chi tiết cái bóng rất đặc sắc. Những đêm chồng đi xa, Vũ Nương chỉ bóng mình trên vách và nói với con đó là cha. Cái bóng vừa gây ra nỗi oan, vừa là chìa khóa để Trương Sinh hiểu ra sự thật. Nó cho thấy tình thương con và nỗi nhớ chồng của nàng.", "type": "slide"}, {"a": 1, "e": "Thủy cung của Linh Phi và cuộc gặp Phan Lang là yếu tố kì ảo.", "o": ["Trương Sinh đi lính", "Vũ Nương sống dưới thủy cung và gặp Phan Lang", "Mẹ chồng Vũ Nương qua đời", "Bé Đản gọi cái bóng là cha"], "p": 4, "q": "Chi tiết nào là yếu tố kì ảo trong truyện?", "type": "q"}, {"b": ["Thương cảm cho số phận người phụ nữ trong xã hội phong kiến.", "Ngợi ca vẻ đẹp phẩm chất của họ.", "Phê phán thói ghen tuông, gia trưởng và xã hội bất công."], "h": "Ý nghĩa tác phẩm", "say": "Qua câu chuyện, tác giả bày tỏ niềm thương cảm cho số phận người phụ nữ trong xã hội phong kiến, ngợi ca vẻ đẹp phẩm chất của họ, đồng thời phê phán thói ghen tuông, gia trưởng và xã hội bất công.", "type": "slide"}, {"a": 0, "e": "Nguyễn Dữ viết Truyền kì mạn lục bằng chữ Hán.", "o": ["Chữ Hán", "Chữ Nôm", "Chữ Quốc ngữ"], "p": 4, "q": "Truyền kì mạn lục được viết bằng chữ gì?", "type": "q"}], "subject": "van", "title": "Chuyện người con gái Nam Xương"}'::jsonb),
